package art.splotch.migration.probe

import android.content.Context
import android.net.ConnectivityManager
import android.net.NetworkCapabilities
import android.net.Uri
import com.facebook.react.ReactPackage
import com.facebook.react.bridge.Arguments
import com.facebook.react.bridge.NativeModule
import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod
import com.facebook.react.uimanager.ViewManager
import java.io.File
import java.security.MessageDigest
import java.util.concurrent.Executors

class SplotchLibraryEnvironment(context: ReactApplicationContext) : ReactContextBaseJavaModule(context) {
  private val MAX_FILE_BYTES = 2097152
  private val HASH_BUFFER_BYTES = 65536
  private val executor = Executors.newSingleThreadExecutor()
  private val root = File(context.filesDir, "splotch-offline-library-v1")
  private var rootReady = false
  private val manager = context.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager
  private fun ensureRoot() {
    if (rootReady) return
    if (!root.exists() && !root.mkdirs()) throw IllegalStateException("Coloring storage is unavailable")
    rootReady = true
  }
  override fun getName() = "SplotchLibraryEnvironment"

  @ReactMethod
  fun environment(promise: Promise) {
    executor.execute {
      try {
        ensureRoot()
        val network = manager.activeNetwork
        val capabilities = manager.getNetworkCapabilities(network)
        val online = capabilities?.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED) == true
        val metered = manager.isActiveNetworkMetered || manager.restrictBackgroundStatus == ConnectivityManager.RESTRICT_BACKGROUND_STATUS_ENABLED
        promise.resolve(Arguments.createMap().apply {
          putString("rootUri", Uri.fromFile(root).toString())
          putBoolean("online", online)
          putBoolean("metered", metered)
        })
      } catch (error: Exception) { promise.reject("library_unavailable", error) }
    }
  }

  @ReactMethod
  fun verify(uri: String, bytes: Double, sha256: String, promise: Promise) {
    executor.execute {
      try {
        ensureRoot()
        val parsedUri = Uri.parse(uri)
        require(parsedUri.scheme == "file")
        val file = File(parsedUri.path ?: "").canonicalFile
        require(file.path.startsWith(root.canonicalPath + File.separator))
        require(bytes > 0 && bytes <= MAX_FILE_BYTES && bytes == bytes.toLong().toDouble())
        require(Regex("^[a-f0-9]{64}$").matches(sha256))
        if (!file.isFile || file.length() != bytes.toLong()) { promise.resolve(false); return@execute }
        val digest = MessageDigest.getInstance("SHA-256")
        file.inputStream().use { input ->
          val buffer = ByteArray(HASH_BUFFER_BYTES)
          var count = input.read(buffer)
          while (count >= 0) { digest.update(buffer, 0, count); count = input.read(buffer) }
        }
        val actual = digest.digest().joinToString("") { "%02x".format(it) }
        promise.resolve(actual == sha256)
      } catch (error: Exception) { promise.reject("library_verify", error) }
    }
  }

  override fun invalidate() { executor.shutdown(); super.invalidate() }
}

class SplotchLibraryPackage : ReactPackage {
  override fun createNativeModules(context: ReactApplicationContext): List<NativeModule> = listOf(SplotchLibraryEnvironment(context))
  override fun createViewManagers(context: ReactApplicationContext): List<ViewManager<*, *>> = emptyList()
}

#import <React/RCTBridgeModule.h>

@interface RCT_EXTERN_MODULE(SplotchLibraryEnvironment, NSObject)
RCT_EXTERN_METHOD(environment:(RCTPromiseResolveBlock)resolve rejecter:(RCTPromiseRejectBlock)reject)
RCT_EXTERN_METHOD(verify:(NSString *)uri bytes:(double)bytes sha256:(NSString *)sha256 resolver:(RCTPromiseResolveBlock)resolve rejecter:(RCTPromiseRejectBlock)reject)
@end

import CryptoKit
import Foundation
import Network
import React

@objc(SplotchLibraryEnvironment)
class SplotchLibraryEnvironment: NSObject, RCTInvalidating {
  private let maxFileBytes = 2097152
  private let hashBufferBytes = 65536
  private let networkWaitSeconds = 3.0
  private let queue = DispatchQueue(label: "art.splotch.offline-library", qos: .utility)
  private let monitor = NWPathMonitor()
  private var currentPath: NWPath?
  private var privateRoot: URL?
  private var pendingEnvironment: [UUID: (NWPath?) -> Void] = [:]

  override init() {
    super.init()
    monitor.pathUpdateHandler = { [weak self] path in
      guard let self else { return }
      self.currentPath = path
      let waiting = Array(self.pendingEnvironment.values)
      self.pendingEnvironment.removeAll()
      waiting.forEach { $0(path) }
    }
    monitor.start(queue: queue)
  }

  deinit { monitor.cancel() }

  @objc func invalidate() {
    monitor.pathUpdateHandler = nil
    monitor.cancel()
    queue.async { [weak self] in
      guard let self else { return }
      let waiting = Array(self.pendingEnvironment.values)
      self.pendingEnvironment.removeAll()
      waiting.forEach { $0(nil) }
    }
  }

  private func root() throws -> URL {
    if let directory = privateRoot { return directory }
    var directory = try FileManager.default.url(for: .applicationSupportDirectory, in: .userDomainMask, appropriateFor: nil, create: true)
      .appendingPathComponent("splotch-offline-library-v1", isDirectory: true)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    var values = URLResourceValues()
    values.isExcludedFromBackup = true
    try directory.setResourceValues(values)
    privateRoot = directory
    return directory
  }

  @objc static func requiresMainQueueSetup() -> Bool { false }

  @objc(environment:rejecter:)
  func environment(_ resolve: @escaping RCTPromiseResolveBlock, rejecter reject: @escaping RCTPromiseRejectBlock) {
    queue.async {
      do {
        let directory = try self.root()
        let finish: (NWPath?) -> Void = { path in
          resolve(["rootUri": directory.absoluteString,
                   "online": path?.status == .satisfied,
                   "metered": path.map { $0.isExpensive || $0.isConstrained } ?? true])
        }
        if let path = self.currentPath { finish(path); return }
        let identity = UUID()
        self.pendingEnvironment[identity] = finish
        self.queue.asyncAfter(deadline: .now() + self.networkWaitSeconds) {
          self.pendingEnvironment.removeValue(forKey: identity)?(nil)
        }
      } catch { reject("library_unavailable", "Coloring storage is unavailable", error) }
    }
  }

  @objc(verify:bytes:sha256:resolver:rejecter:)
  func verify(_ uri: String, bytes: Double, sha256: String, resolver resolve: @escaping RCTPromiseResolveBlock, rejecter reject: @escaping RCTPromiseRejectBlock) {
    queue.async {
      do {
        let directory = try self.root().resolvingSymlinksInPath().standardizedFileURL
        guard let url = URL(string: uri), url.isFileURL,
              url.resolvingSymlinksInPath().standardizedFileURL.path.hasPrefix(directory.path + "/"),
              bytes > 0, bytes <= Double(self.maxFileBytes), bytes.rounded() == bytes,
              sha256.range(of: "^[a-f0-9]{64}$", options: .regularExpression) != nil else {
          throw NSError(domain: "SplotchLibrary", code: 1)
        }
        let properties = try url.resourceValues(forKeys: [.fileSizeKey, .isRegularFileKey])
        guard properties.isRegularFile == true, properties.fileSize == Int(bytes) else { resolve(false); return }
        let handle = try FileHandle(forReadingFrom: url)
        defer { try? handle.close() }
        var digest = SHA256()
        while let data = try handle.read(upToCount: self.hashBufferBytes), !data.isEmpty { digest.update(data: data) }
        resolve(digest.finalize().map { String(format: "%02x", $0) }.joined() == sha256)
      } catch { reject("library_verify", "Coloring verification failed", error) }
    }
  }
}
